or host paths outside the jail use shell::fs::*.","function_id":"coder::update-file","registered_triggers":[],"request_schema":{"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"UpdateFileSpec":{"properties":{"ops":{"items":{"$ref":"#/definitions/UpdateOp"},"type":"array"},"path":{"description":"Path relative to the primary allowed root, or an absolute path inside any allowed root. Call `coder::info` to see the allowed roots. Paths outside every allowed root are rejected — use the shell worker's `shell::fs::*` for host paths outside the jail.","type":"string"}},"required":["ops","path"],"type":"object"},"UpdateOp":{"oneOf":[{"description":"Insert `content` before line `at_line` (1-based). `at_line = lines+1` appends to end of file.","properties":{"at_line":{"format":"uint32","minimum":0.0,"type":"integer"},"content":{"type":"string"},"op":{"enum":["insert"],"type":"string"}},"required":["at_line","content","op"],"type":"object"},{"description":"Delete lines `from_line..=to_line` (1-based, inclusive).","properties":{"from_line":{"format":"uint32","minimum":0.0,"type":"integer"},"op":{"enum":["remove"],"type":"string"},"to_line":{"format":"uint32","minimum":0.0,"type":"integer"}},"required":["from_line","op","to_line"],"type":"object"},{"description":"Overwrite lines `from_line..=to_line` with `content`.","properties":{"content":{"type":"string"},"from_line":{"format":"uint32","minimum":0.0,"type":"integer"},"op":{"enum":["update_lines"],"type":"string"},"to_line":{"format":"uint32","minimum":0.0,"type":"integer"}},"required":["content","from_line","op","to_line"],"type":"object"},{"description":"Replace all regex matches in the file body (after line ops).","properties":{"dot_matches_newline":{"default":false,"description":"When true, `.` in `pattern` also matches `\n`, so a short anchored pattern like `"fn parse_config\\(.*?\\n\\}"` replaces a whole multi-line region without quoting it — prefer two short anchors joined by `.*?` over pasting the block into the pattern. Without this flag (the default), `.` does not cross newlines and a multi-line pattern silently matches nothing.","type":"boolean"},"expect_matches":{"default":null,"description":"Expected number of matches for this op. When set and the actual count differs, this FILE fails with C210 and nothing is written to it (other files in the batch still apply). Set `expect_matches: 1` to make a targeted read-free edit safe — a mismatch means the pattern is anchored too loosely or matches nothing. Set `expect_matches: 0` to assert ABSENCE: the op succeeds only when nothing matches (the replacement is unused). Omit to replace all matches unconditionally.","format":"uint64","minimum":0.0,"type":["integer","null"]},"ignore_case":{"default":false,"type":"boolean"},"op":{"enum":["replace"],"type":"string"},"pattern":{"type":"string"},"replacement":{"description":"Substitution text for each match. Capture references expand: `$1`/`${1}` by index (`$0` is the whole match) and `$name`/`${name}` by name. A literal `$` MUST be written `$$` — JS/TS template literals in a replacement are the classic collision: write `Hello, $${name}!` to output `Hello, ${name}!`. Unbraced references consume the longest `[0-9A-Za-z_]` run, so `$1a` means a group named "1a", NOT group 1 then "a" (use `${1}a`). A reference to a group the pattern does not define fails pre-write with C210 — nothing is written. References are validated even when the replacement goes unused (e.g. `expect_matches: 0`): the replacement must be well-formed even when unused.","type":"string"}},"required":["op","pattern","replacement"],"type":"object"}]}},"examples":[{"files":[{"ops":[{"at_line":1,"content":"// generated by coder
